import random
import itertools

n = 28
min_deg = 4
max_deg = 7

def check_girth(adj, n, max_cycle=5):
    """Check if graph has any cycle of length <= max_cycle"""
    for start in range(n):
        # BFS to find shortest cycle through start
        visited = {start: (0, -1)}  # node -> (depth, parent)
        queue = [start]
        idx = 0
        while idx < len(queue):
            node = queue[idx]
            idx += 1
            depth, parent = visited[node]
            if depth >= max_cycle:
                continue
            for neighbor in adj[node]:
                if neighbor == parent:
                    continue
                if neighbor in visited:
                    cycle_len = depth + visited[neighbor][0] + 1
                    if cycle_len <= max_cycle:
                        return False, cycle_len
                else:
                    visited[neighbor] = (depth + 1, node)
                    queue.append(neighbor)
    return True, None

def build_graph_greedy(n, min_deg, max_deg, seed=42):
    random.seed(seed)

    # Start with empty graph
    adj = {i: set() for i in range(n)}
    edges = set()

    # Try to add edges while maintaining girth >= 6
    all_possible = [(i, j) for i in range(n) for j in range(i+1, n)]
    random.shuffle(all_possible)

    for u, v in all_possible:
        if len(adj[u]) >= max_deg or len(adj[v]) >= max_deg:
            continue

        # Check if adding this edge creates a short cycle
        # Adding edge (u,v) creates a cycle of length k if there's a path of length k-1 between u and v
        # We need to check paths of length 2, 3, 4 (which would create cycles of length 3, 4, 5)

        # Check for path of length 2 (would create triangle)
        if adj[u] & adj[v]:
            continue

        # Check for path of length 3 (would create 4-cycle)
        # Path u-x-y-v means x in adj[u], y in adj[v], and x-y is an edge
        has_4cycle = False
        for x in adj[u]:
            for y in adj[v]:
                if y in adj[x]:
                    has_4cycle = True
                    break
            if has_4cycle:
                break
        if has_4cycle:
            continue

        # Check for path of length 4 (would create 5-cycle)
        # Path u-x-y-z-v
        has_5cycle = False
        for x in adj[u]:
            for y in adj[x]:
                if y == u or y == v:
                    continue
                for z in adj[y]:
                    if z == x or z == u:
                        continue
                    if z in adj[v]:
                        has_5cycle = True
                        break
                if has_5cycle:
                    break
            if has_5cycle:
                break
        if has_5cycle:
            continue

        # Add the edge
        adj[u].add(v)
        adj[v].add(u)
        edges.add((u, v))

    return adj, edges

# Try multiple seeds
best_adj = None
best_edges = None
best_min_deg = 0

for seed in range(100):
    adj, edges = build_graph_greedy(n, min_deg, max_deg, seed)
    degrees = [len(adj[i]) for i in range(n)]
