import random
import itertools

n = 28
min_deg = 4
max_deg = 7

def check_girth(adj, n, max_cycle=5):
    """Check if graph has any cycle of length <= max_cycle"""
    for start in range(n):
        visited = {start: (0, -1)}
        queue = [start]
        idx = 0
        while idx < len(queue):
            node = queue[idx]
            idx += 1
            depth, parent = visited[node]
            if depth >= max_cycle:
                continue
            for neighbor in adj[node]:
                if neighbor == parent:
                    continue
                if neighbor in visited:
                    cycle_len = depth + visited[neighbor][0] + 1
                    if cycle_len <= max_cycle:
                        return False, cycle_len
                else:
                    visited[neighbor] = (depth + 1, node)
                    queue.append(neighbor)
    return True, None

def can_add_edge(adj, u, v, n):
    """Check if adding edge (u,v) would create a cycle of length <= 5"""
    # Check for path of length 2 (triangle)
    if adj[u] & adj[v]:
        return False

    # Check for path of length 3 (4-cycle)
    for x in adj[u]:
        for y in adj[v]:
            if y in adj[x]:
                return False

    # Check for path of length 4 (5-cycle)
    for x in adj[u]:
        for y in adj[x]:
            if y == u or y == v:
                continue
            for z in adj[y]:
                if z == x or z == u:
                    continue
                if z in adj[v]:
                    return False

    return True

def remove_edge_check(adj, u, v, n):
    """Remove edge and check if girth is still maintained (always true when removing)"""
    adj[u].discard(v)
    adj[v].discard(u)
    return True

# Try simulated annealing / local search
def local_search(n, min_deg, max_deg, seed=0, iterations=100000):
    random.seed(seed)

    # Start with empty graph
    adj = {i: set() for i in range(n)}
    edges = set()

    # Phase 1: Build a maximal girth-6 graph greedily
    all_possible = [(i, j) for i in range(n) for j in range(i+1, n)]
    random.shuffle(all_possible)

    for u, v in all_possible:
        if len(adj[u]) >= max_deg or len(adj[v]) >= max_deg:
            continue
        if can_add_edge(adj, u, v, n):
            adj[u].add(v)
            adj[v].add(u)
            edges.add((u, v))

    # Phase 2: Try to fix low-degree vertices
    for iteration in range(iterations):
        degrees = [len(adj[i]) for i in range(n)]
        min_d = min(degrees)

        if min_d >= min_deg:
            return adj, edges, True

        # Find a low-degree vertex
        low_vertices = [i for i in range(n) if degrees[i] < min_deg]
        if not low_vertices:
            break

        v = random.choice(low_vertices)

        # Try to add an edge from v to some non-neighbor
        non_neighbors = [u for u in range(n) if u != v and u not in adj[v] and len(adj[u]) < max_deg]
        random.shuffle(non_neighbors)

        added = False
        for u in non_neighbors:
            if can_add_edge(adj, u, v, n):
                adj[u].add(v)
                adj[v].add(u)
                edges.add((min(u,v), max(u,v)))
                added = True
                break

        if not added:
            # Try removing an edge and adding two new ones
            if adj[v]:
                w = random.choice(list(adj[v]))
                adj[v].discard(w)
                adj[w].discard(v)
                edges.discard((min(v,w), max(v,w)))

                # Try to add edges from v and w
                for u in range(n):
                    if u != v and u not in adj[v] and len(adj[u]) < max_deg:
                        if can_add_edge(adj, u, v, n):
                            adj[u].add(v)
                            adj[v].add(u)
                            edges.add((min(u,v), max(u,v)))
                            break

                for u in range(n):
                    if u != w and u not in adj[w] and len(adj[u]) < max_deg:
                        if can_add_edge(adj, u, w, n):
                            adj[u].add(w)
                            adj[w].add(u)
                            edges.add((min(u,w), max(u,w)))
                            break

    return adj, edges, False

# Try many seeds
for seed in range(200):
    adj, edges, success = local_search(n, min_deg, max_deg, seed, 50000)
    degrees = [len(adj[i]) for i in range(n)]
    min_d = min(degrees)
    if min_d >= min_deg:
        ok, cycle_len = check_girth(adj, n, 5)
        if ok:
            print(f"SUCCESS with seed {seed}!")
            print(f"Degrees: min={min_d}, max={max(degrees)}")
            edge_list = sorted(edges)
            print("Edges:", edge_list)
            break
    if seed % 20 == 0:
        print(f"Seed {seed}: min_degree={min_d}")

from pysat.solvers import Glucose3
from pysat.card import *
import itertools

n = 28

edge_idx = {}
idx = 0
for i in range(n):
    for j in range(i+1, n):
        edge_idx[(i,j)] = idx
        idx += 1

num_edges = idx
print(f"Number of edge variables: {num_edges}")

solver = Glucose3()

# Degree constraints
for v in range(n):
    edge_vars = []
    for u in range(v):
        edge_vars.append(edge_idx[(u,v)] + 1)
    for u in range(v+1, n):
        edge_vars.append(edge_idx[(v,u)] + 1)

    # At least 4
    clauses_atleast = CardEnc.atleast(edge_vars, 4, v1=num_edges+1)
    for clause in clauses_atleast:
        solver.add_clause(clause)
    # At most 7
    clauses_atmost = CardEnc.atmost(edge_vars, 7, v1=num_edges+1)
    for clause in clauses_atmost:
        solver.add_clause(clause)

print("Added degree constraints")

# No triangles
for i, j, k in itertools.combinations(range(n), 3):
    e1 = edge_idx.get((min(i,j), max(i,j)))
    e2 = edge_idx.get((min(j,k), max(j,k)))
    e3 = edge_idx.get((min(i,k), max(i,k)))
    if e1 is not None and e2 is not None and e3 is not None:
        solver.add_clause([-(e1+1), -(e2+1), -(e3+1)])

print("Added triangle constraints")

# No 4-cycles
count4 = 0
for i, j, k, l in itertools.combinations(range(n), 4):
    cycles = [
        [(i,j), (j,k), (k,l), (l,i)],
        [(i,j), (j,l), (l,k), (k,i)],
        [(i,k), (k,j), (j,l), (l,i)]
    ]
    for cycle in cycles:
        edge_vars = []
        valid = True
        for u, v in cycle:
            key = (min(u,v), max(u,v))
            if key in edge_idx:
                edge_vars.append(edge_idx[key] + 1)
            else:
                valid = False
                break
        if valid:
            solver.add_clause([-x for x in edge_vars])
            count4 += 1

print(f"Added {count4} 4-cycle constraints")

# No 5-cycles
count5 = 0
for a, b, c, d, e in itertools.combinations(range(n), 5):
    vertices = [a, b, c, d, e]
    from itertools import permutations
    seen = set()
    for perm in permutations(vertices[1:]):
        cycle = [vertices[0]] + list(perm)
        rotations = []
        for i in range(5):
            rotations.append(tuple(cycle[i:] + cycle[:i]))
            rotations.append(tuple(cycle[i::-1] + cycle[:i:-1]))
        cycle_key = min(rotations)
        if cycle_key in seen:
            continue
        seen.add(cycle_key)

        edge_vars = []
        valid = True
        for idx in range(5):
            u, v = cycle[idx], cycle[(idx+1) % 5]
            key = (min(u,v), max(u,v))
            if key in edge_idx:
                edge_vars.append(edge_idx[key] + 1)
            else:
                valid = False
                break
        if valid:
            solver.add_clause([-x for x in edge_vars])
            count5 += 1

print(f"Added {count5} 5-cycle constraints")

print("Solving...")
if solver.solve():
    model = solver.get_model()
    edge_list = []
    for (i,j), idx in edge_idx.items():
        if model[idx] > 0:
            edge_list.append((i,j))
    print(f"Found graph with {len(edge_list)} edges")

    adj = {i: set() for i in range(n)}
    for u, v in edge_list:
        adj[u].add(v)
        adj[v].add(u)

    degrees = [len(adj[i]) for i in range(n)]
    print(f"Degrees: min={min(degrees)}, max={max(degrees)}")

    # Verify girth
    min_cycle = float('inf')
    for start in range(n):
        visited = {start: (0, -1)}
        queue = [start]
        qi = 0
        while qi < len(queue):
            node = queue[qi]
            qi += 1
            depth, parent = visited[node]
            if depth >= min_cycle:
                continue
            for neighbor in adj[node]:
                if neighbor == parent:
                    continue
                if neighbor in visited:
                    cycle_len = depth + visited[neighbor][0] + 1
                    if cycle_len < min_cycle:
                        min_cycle = cycle_len
                else:
                    visited[neighbor] = (depth + 1, node)
                    queue.append(neighbor)

    print(f"Girth: {min_cycle}")
    print("Edges:", sorted(edge_list))
else:
    print("UNSATISFIABLE")
